&lt;div class=&quot;presentation navmenudroite&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt;Les arch&#233;types de druide&lt;a class=&quot;headeranchor&quot; id=&quot;Les_arch&#233;types_de_druide_0&quot; href=&quot;#Les_arch&#233;types_de_druide_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&amp;nbsp;Retour &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html&quot; title=&quot;Le druide&quot;&gt;classe&lt;/a&gt;.
&lt;ul style=&quot;margin-top:2px&quot;&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Adepte-Ondin-(Druide).html&quot; title=&quot;Adepte ondin&quot;&gt;Adepte ondin&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Ondin-(Race).html&quot; title=&quot;Les ondins&quot;&gt;Ondin&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ami-Des-F&#233;es-(Druide).html&quot; title=&quot;Ami des f&#233;es&quot;&gt;Ami des f&#233;es&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Arpenteur-De-Monde-(Druide).html&quot; title=&quot;Arpenteur de monde&quot;&gt;Arpenteur de monde&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Aspirant-Naga-(Druide).html&quot; title=&quot;Aspirant naga&quot;&gt;Aspirant naga&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Nagaji-(Race).html&quot; title=&quot;Les nagajis&quot;&gt;nagaji&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chamanes-Animaux-(Druide).html&quot; title=&quot;Chamanes animaux&quot;&gt;Chamanes animaux&lt;/a&gt; (MJRA,AG,AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Changepeau-(Druide).html&quot; title=&quot;Changepeau&quot;&gt;Changepeau&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chanteur-Sylvestre-(Druide).html&quot; title=&quot;Chanteur sylvestre&quot;&gt;Chanteur sylvestre&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Elfe.html&quot; title=&quot;Les elfes&quot;&gt;Elfe&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chuchoteur-Sauvage-(Druide).html&quot; title=&quot;Chuchoteur sauvage&quot;&gt;Chuchoteur sauvage&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Croc-De-La-Nature-(Druide).html&quot; title=&quot;Croc de la nature&quot;&gt;Croc de la nature&lt;/a&gt; (MCA) &lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Aquatique-(Druide).html&quot; title=&quot;Druide aquatique&quot;&gt;Druide aquatique&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Arctique-(Druide).html&quot; title=&quot;Druide arctique&quot;&gt;Druide arctique&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-De-La-Jungle-(Druide).html&quot; title=&quot;Druide de la jungle&quot;&gt;Druide de la jungle&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Des-Cavernes-(Druide).html&quot; title=&quot;Druide des cavernes&quot;&gt;Druide des cavernes&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Des-D&#233;serts-(Druide).html&quot; title=&quot;Druide des d&#233;serts&quot;&gt;Druide des d&#233;serts&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Des-Marais-(Druide).html&quot; title=&quot;Druide des marais&quot;&gt;Druide des marais&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Des-Montagnes-(Druide).html&quot; title=&quot;Druide des montagnes&quot;&gt;Druide des montagnes&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Des-Ouragans-(Druide).html&quot; title=&quot;Druide des ouragans&quot;&gt;Druide des ouragans&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Des-Plaines-(Druide).html&quot; title=&quot;Druide des plaines&quot;&gt;Druide des plaines&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Des-Temp&#234;tes-(Druide).html&quot; title=&quot;Druide des temp&#234;tes&quot;&gt;Druide des temp&#234;tes&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Du-Ciel-(Druide).html&quot; title=&quot;Druide du ciel&quot;&gt;Druide du ciel&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Sylphe-(Race).html&quot; title=&quot;Les sylphes&quot;&gt;Sylphe&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-R&#233;incarn&#233;-(Druide).html&quot; title=&quot;Druide r&#233;incarn&#233;&quot;&gt;Druide r&#233;incarn&#233;&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Urbain-(Druide).html&quot; title=&quot;Druide urbain&quot;&gt;Druide urbain&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Enfant-De-La-Lune-(Druide).html&quot; title=&quot;Enfant de la lune&quot;&gt;Enfant de la lune&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Enfant-Sauvage-(Druide).html&quot; title=&quot;Enfant sauvage&quot;&gt;Enfant sauvage&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Humain.html&quot; title=&quot;Les humains&quot;&gt;Humain&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Fl&#233;trisseur-(Druide).html&quot; title=&quot;Fl&#233;trisseur&quot;&gt;Fl&#233;trisseur&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gardien-Antique-(Druide).html&quot; title=&quot;Gardien antique&quot;&gt;Gardien antique&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Homme-Serpent.html&quot; title=&quot;Homme-serpent&quot;&gt;Homme-serpent&lt;/a&gt;) (CM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;M&#233;tamorphe-Sauvage-(Druide).html&quot; title=&quot;M&#233;tamorphe sauvage&quot;&gt;M&#233;tamorphe sauvage&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sage-Des-Menhirs-(Druide).html&quot; title=&quot;Sage des menhirs&quot;&gt;Sage des menhirs&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Seigneur-De-La-Meute-(Druide).html&quot; title=&quot;Seigneur de la meute&quot;&gt;Seigneur de la meute&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Surnaturaliste-(Druide).html&quot; title=&quot;Surnaturaliste&quot;&gt;Surnaturaliste&lt;/a&gt; (&lt;i&gt;OO&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Troll-Furieux-(Druide).html&quot; title=&quot;Troll furieux&quot;&gt;Troll furieux&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Troll.html&quot; title=&quot;Troll&quot;&gt;Troll&lt;/a&gt;) (CM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Urushiol-(Druide).html&quot; title=&quot;Urushiol&quot;&gt;Urushiol&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des joueurs - R&#232;gles avanc&#233;es (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Player&#39;s Guide/Manuel des joueurs - R&#232;gles avanc&#233;es&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAPG.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;i&gt;Serviteurs d&#233;vou&#233;s d’une nature corrompue, ruin&#233;e et d&#233;truite, les fl&#233;trisseurs prennent soin des terres ravag&#233;es par une catastrophe naturelle. Si certains se consacrent &#224; r&#233;g&#233;n&#233;rer les endroits que la civilisation a souill&#233;s afin de les rendre &#224; la nature, d’autres recherchent la violence qui lui est propre et festoient sur la pourriture et la d&#233;composition qui mettent fin &#224; toute chose.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Pacte avec la nature (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Pacte_avec_la_nature_Ext_0&quot; href=&quot;#Pacte_avec_la_nature_Ext_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Un fl&#233;trisseur ne peut avoir de &lt;a class=&quot;pagelink&quot; href=&quot;Compagnons-Animaux.html&quot; title=&quot;Les compagnons animaux du druide&quot;&gt;compagnon animal&lt;/a&gt;, mais peut par contre appeler un &lt;a class=&quot;pagelink&quot; href=&quot;Familiers.html&quot; title=&quot;familier&quot;&gt;familier&lt;/a&gt; comme un &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt; du m&#234;me &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt; que son &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html&quot; title=&quot;Le druide&quot;&gt;druide&lt;/a&gt;, ou bien avoir acc&#232;s aux domaines de &lt;a class=&quot;pagelink&quot; href=&quot;Domaine-De-Lobscurit&#233;.html&quot; title=&quot;Domaine de l&amp;#39;Obscurit&#233;&quot;&gt;l’Obscurit&#233;&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Domaine-De-La-Mort.html&quot; title=&quot;Domaine de la Mort&quot;&gt;de la Mort&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Domaine-De-La-Destruction.html&quot; title=&quot;Domaine de la Destruction&quot;&gt;de la Destruction&lt;/a&gt; en plus de ceux normalement permis &#224; sa classe.&lt;br /&gt;&lt;br /&gt;
&lt;h3 class=&quot;separator&quot;&gt;Ami de la vermine (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Ami_de_la_vermine_Sur_1&quot; href=&quot;#Ami_de_la_vermine_Sur_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Le personnage peut am&#233;liorer l’attitude Inamicale de d&#233;part des insectes &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#EMPATHIENAIMALE&quot; title=&quot;Le druide&quot;&gt;de la m&#234;me mani&#232;re&lt;/a&gt; qu’un &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html&quot; title=&quot;Le druide&quot;&gt;druide&lt;/a&gt; le fait avec les &lt;a class=&quot;pagelink&quot; href=&quot;Type-Animal.html&quot; title=&quot;Animal&quot;&gt;animaux&lt;/a&gt;. S’il accepte de subir une p&#233;nalit&#233; de -4 sur son &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Jettest.html&quot; title=&quot;test&quot;&gt;je&lt;/a&gt;t, il peut faire de m&#234;me avec les &lt;a class=&quot;pagelink&quot; href=&quot;Type-Animal.html&quot; title=&quot;Animal&quot;&gt;animaux&lt;/a&gt; et les cr&#233;atures &lt;a class=&quot;pagelink&quot; href=&quot;Type-Mort-Vivant.html&quot; title=&quot;Mort-vivant&quot;&gt;morts-vivants&lt;/a&gt; d&#233;nu&#233;s d’&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt; qui &#233;taient auparavant des &lt;a class=&quot;pagelink&quot; href=&quot;Type-Animal.html&quot; title=&quot;Animal&quot;&gt;animaux&lt;/a&gt;. Cette p&#233;nalit&#233; ne s’applique pas s’ils poss&#232;dent l’attaque sp&#233;ciale &lt;a class=&quot;pagelink&quot; href=&quot;Maladie-(Capacit&#233;).html&quot; title=&quot;Maladie (Ext ou Sur)&quot;&gt;maladie&lt;/a&gt;. Cette capacit&#233; remplace &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#EMPATHIESAUVAGE&quot; title=&quot;Le druide&quot;&gt;empathie sauvage&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;
&lt;h3 class=&quot;separator&quot;&gt;Miasme (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Miasme_Ext_2&quot; href=&quot;#Miasme_Ext_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&#192; partir du &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt; 5, si le &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html&quot; title=&quot;Le druide&quot;&gt;druide&lt;/a&gt; occupe l’espace voisin de celui d’une cr&#233;ature au d&#233;but du &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt; de celle-ci, elle doit r&#233;ussir un &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;jet de sauvegarde&quot;&gt;jet de Vigueur&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; 10 + la moiti&#233; du &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html&quot; title=&quot;Le druide&quot;&gt;druide&lt;/a&gt; + le modificateur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Sagesse.html&quot; title=&quot;La Sagesse&quot;&gt;Sagesse&lt;/a&gt; du &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html&quot; title=&quot;Le druide&quot;&gt;druide&lt;/a&gt;) ou &#234;tre &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Fi&#233;vreux.html&quot; title=&quot;Fi&#233;vreux&quot;&gt;fi&#233;vreuse&lt;/a&gt; pendant 1 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt;. Si elle poss&#232;de le &lt;a class=&quot;pagelink&quot; href=&quot;Type-Animal.html&quot; title=&quot;Animal&quot;&gt;type animal&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Type-F&#233;e.html&quot; title=&quot;F&#233;e&quot;&gt;f&#233;e&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Type-Plante.html&quot; title=&quot;Plante&quot;&gt;plante&lt;/a&gt; et qu’elle rate ce &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;jet de sauvegarde&quot;&gt;jet de Vigueur&lt;/a&gt;, elle est &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Naus&#233;eux.html&quot; title=&quot;Naus&#233;eux&quot;&gt;naus&#233;euse&lt;/a&gt; durant 1 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Fi&#233;vreux.html&quot; title=&quot;Fi&#233;vreux&quot;&gt;fi&#233;vreuse&lt;/a&gt; durant la minute suivante. Si elle le r&#233;ussit, elle est immunis&#233;e aux effets de ce pouvoir pendant 24 heures, comme le sont les cr&#233;atures immunis&#233;es aux &lt;a class=&quot;pagelink&quot; href=&quot;Maladies.html&quot; title=&quot;Les maladies&quot;&gt;maladies&lt;/a&gt;. Cette capacit&#233; remplace &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#ABSENCEDETRACES&quot; title=&quot;Le druide&quot;&gt;absence de traces&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#RESISTANCEALAPPELDELANATURE&quot; title=&quot;Le druide&quot;&gt;r&#233;sistance &#224; l’appel de la nature&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;
&lt;h3 class=&quot;separator&quot;&gt;B&#233;n&#233;diction de la fl&#233;trissure (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;B&#233;n&#233;diction_de_la_fl&#233;trissure_Ext_3&quot; href=&quot;#B&#233;n&#233;diction_de_la_fl&#233;trissure_Ext_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt; 9, le personnage est immunis&#233; &#224; toutes les &lt;a class=&quot;pagelink&quot; href=&quot;Maladies.html&quot; title=&quot;Les maladies&quot;&gt;maladies&lt;/a&gt; naturelles et surnaturelles, ainsi qu’aux effets qui pourraient le rendre malade ou &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Naus&#233;eux.html&quot; title=&quot;Naus&#233;eux&quot;&gt;naus&#233;eux&lt;/a&gt;. Cette capacit&#233; remplace &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#IMMUNITECONTRELEVENIN&quot; title=&quot;Le druide&quot;&gt;immunit&#233; contre le venin&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;
&lt;h3 class=&quot;separator&quot;&gt;Vecteur de la peste (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Vecteur_de_la_peste_Sur_4&quot; href=&quot;#Vecteur_de_la_peste_Sur_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&#192; partir du &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt; 13, si une cr&#233;ature r&#233;ussit une attaque de corps &#224; corps, une attaque &#224; mains nues ou une attaque avec une arme naturelle sur le &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html&quot; title=&quot;Le druide&quot;&gt;druide&lt;/a&gt;, elle doit r&#233;ussir un &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;jet de sauvegarde&quot;&gt;jet de Vigueur&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; 10 + la moiti&#233; du &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html&quot; title=&quot;Le druide&quot;&gt;druide&lt;/a&gt; + le modificateur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Sagesse.html&quot; title=&quot;La Sagesse&quot;&gt;Sagesse&lt;/a&gt; du &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html&quot; title=&quot;Le druide&quot;&gt;druide&lt;/a&gt;) sous peine de contracter une &lt;a class=&quot;pagelink&quot; href=&quot;Maladies.html&quot; title=&quot;maladie&quot;&gt;maladie&lt;/a&gt;, comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Contagion.html&quot; title=&quot;Contagion&quot;&gt;contagion&lt;/a&gt;&lt;/i&gt;. Si elle y parvient, elle est immunis&#233;e aux effets de ce pouvoir pendant 24 heures. Cette capacit&#233; remplace &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#MILLEVISAGES&quot; title=&quot;Le druide&quot;&gt;mille visages&lt;/a&gt;.
